import { gsap } from 'gsap';
import { uv, vec2, vec3, length, smoothstep, mix } from 'three/tsl';
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, SphereGeometry, DirectionalLight, Color, MathUtils, MeshPhysicalMaterial } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#14141a', ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 0.55, hex: '#101017' }, { at: 1, hex: '#16161d' }],
  };

  const root = new Group();
  root.name = 'orbit-product-hero';

  const disposables = [];
  const tweens = [];
  const primitiveHandles = [];

  // ---------- BACKDROP (7x6 at z=-2.5, vertical engineered gradient) ----------
  const stops = colors.gradientStops ?? [{ at: 0, hex: colors.background }, { at: 1, hex: colors.ink }];
  const c0 = new Color(stops[0]?.hex ?? '#0b0b10');
  const c1 = new Color(stops[1]?.hex ?? stops[0]?.hex ?? '#101017');
  const c2 = new Color(stops[2]?.hex ?? stops[1]?.hex ?? '#16161d');
  const mid = stops[1]?.at ?? 0.55;

  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const y = uv().y;
  const gA = mix(vec3(c0.r, c0.g, c0.b), vec3(c1.r, c1.g, c1.b), smoothstep(0.0, mid, y));
  const gradient = mix(gA, vec3(c2.r, c2.g, c2.b), smoothstep(mid, 1.0, y));
  backdropMat.colorNode = gradient;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(() => { backdropGeo.dispose(); backdropMat.dispose(); });

  // ---------- PRODUCT GROUP (watch + plinth), receives orbit + hover tilt ----------
  const productGroup = new Group();
  productGroup.name = 'product-group';
  root.add(productGroup);

  // Plinth: radius 1.4, height 0.25, top face at y=-1.1
  const plinthGeo = new CylinderGeometry(1.4, 1.4, 0.25, 64);
  const plinthMat = new MeshPhysicalNodeMaterial();
  plinthMat.color = new Color(colors.surface ?? '#14141a');
  plinthMat.roughness = 0.7;
  plinthMat.metalness = 0.3;
  const plinth = new Mesh(plinthGeo, plinthMat);
  plinth.position.set(0, -1.1 - 0.125, 0);
  productGroup.add(plinth);
  disposables.push(() => { plinthGeo.dispose(); plinthMat.dispose(); });

  // Contact shadow (radial, radius 1.6, opacity 0.55)
  const shadowGeo = new PlaneGeometry(3.2, 3.2);
  const shadowMat = new MeshBasicNodeMaterial();
  const centered = uv().sub(vec2(0.5, 0.5));
  const dist = length(centered).mul(2.0);
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = smoothstep(1.0, 0.0, dist).mul(0.55);
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -1.351, 0);
  productGroup.add(contactShadow);
  disposables.push(() => { shadowGeo.dispose(); shadowMat.dispose(); });

  // Accent signal light indicator on left bezel flank
  const signalGeo = new SphereGeometry(0.055, 16, 16);
  const signalMat = new MeshPhysicalNodeMaterial();
  signalMat.color = new Color(colors.accent ?? '#ff2a38');
  signalMat.emissive = new Color(colors.accent ?? '#ff2a38');
  signalMat.emissiveIntensity = 1.6;
  signalMat.roughness = 0.4;
  signalMat.metalness = 0.1;
  const signalLight = new Mesh(signalGeo, signalMat);
  signalLight.position.set(-1.0, 0.12, 0.32);
  productGroup.add(signalLight);
  disposables.push(() => { signalGeo.dispose(); signalMat.dispose(); });

  // Rim/accent light grazing left flank (node-local, capped)
  const rimLight = new DirectionalLight(new Color(colors.accent ?? '#ff2a38'), 0.75);
  rimLight.position.set(-3.2, 1.6, 2.2);
  root.add(rimLight);

  // ---------- WATCH MESH (async, normalized to 2.2 units tall) ----------
  const watchHolder = new Group();
  productGroup.add(watchHolder);

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene ?? gltf.scenes?.[0];
    if (!scene) return;

    const box = new THREE.Box3().setFromObject(scene);
    const size = new THREE.Vector3();
    box.getSize(size);
    const center = new THREE.Vector3();
    box.getCenter(center);
    scene.position.sub(center);

    const targetHeight = 2.2;
    const scale = size.y > 0 ? targetHeight / size.y : 1;
    watchHolder.scale.setScalar(scale);

    scene.traverse((child) => {
      if (child.isMesh && child.material) {
        const src = child.material;
        const newMat = new MeshPhysicalMaterial({
          map: src.map ?? null,
          normalMap: src.normalMap ?? null,
          roughnessMap: src.roughnessMap ?? null,
          metalnessMap: src.metalnessMap ?? null,
          color: src.color ? src.color.clone() : new Color(0xdddddd),
          roughness: 0.52,
          metalness: 0.55,
          clearcoat: 0.2,
          clearcoatRoughness: 0.4,
        });
        if ('anisotropy' in newMat) {
          newMat.anisotropy = 0.8;
          newMat.anisotropyRotation = 0;
        }
        child.material = newMat;
        disposables.push(() => newMat.dispose());
      }
    });

    watchHolder.add(scene);
    disposables.push(() => {
      scene.traverse((c) => { if (c.isMesh && c.geometry) c.geometry.dispose(); });
    });

    // entrance: weighted settle overshoot
    productGroup.scale.setScalar(0.94);
    const tw = gsap.to(productGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
    tweens.push(tw);
  }).catch(() => {});

  // ---------- TEXT ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'Calibre NA-01', role: 'headline', typography: { fontSize: 68 } },
    { text: 'Machined in-house. 41 mm. Grade 5 titanium.', role: 'body', typography: { fontSize: 26 } },
    { text: 'FROM 4200 USD / SHIPS IN 21 DAYS', role: 'caption', typography: { fontSize: 18 } },
  ];

  const textObjects = [];
  const paper = colors.paper ?? '#e8ecf2';

  for (const item of items) {
    const role = item.role ?? 'body';
    const fontSize = item.typography?.fontSize ?? (role === 'headline' ? 68 : role === 'caption' ? 18 : 26);
    let posY = -1.5;
    let letterSpacingPx = 0;
    let align = 'center';
    if (role === 'headline') { posY = -1.5; }
    else if (role === 'body') { posY = -1.8; }
    else if (role === 'caption') { posY = -2.05; letterSpacingPx = fontSize * 0.08; }

    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: paper,
      align,
      letterSpacingPx,
    });
    textObj.position.set(0, posY, 0.05);
    textObj.userData.baseY = posY;
    root.add(textObj);
    textObjects.push(textObj);

    const tw = gsap.fromTo(
      textObj.position,
      { y: posY + 0.2 },
      { y: posY, duration: 0.6, ease: 'power2.out', delay: 0.1 }
    );
    tweens.push(tw);
    if (textObj.material) {
      textObj.material.transparent = true;
      textObj.material.opacity = 0;
      const twOp = gsap.to(textObj.material, { opacity: 1, duration: 0.6, ease: 'power2.out', delay: 0.1 });
      tweens.push(twOp);
    }
  }

  // ---------- CINEMATIC PRIMITIVES ----------
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const prim of primitiveConfigs) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn !== 'function') continue;
    const target = prim.name === 'depth-rotate' || prim.name === 'orbit' ? productGroup : root;
    try {
      const handle = fn(target, { ...(prim.params ?? {}), trigger: prim.trigger });
      primitiveHandles.push(handle);
    } catch (e) {
      // ignore primitive failure to keep node resilient
    }
  }

  // ---------- HOVER TILT (manual fallback, weighted settle release) ----------
  const baseRotX = productGroup.rotation.x;
  const baseRotZ = productGroup.rotation.z;

  root.userData.handlers = {
    pointerover: () => {
      const tw = gsap.to(productGroup.rotation, {
        x: baseRotX + MathUtils.degToRad(6),
        duration: 0.3,
        ease: 'power2.out',
      });
      tweens.push(tw);
    },
    pointerout: () => {
      const tl = gsap.timeline();
      tl.to(productGroup.rotation, {
        x: baseRotX - MathUtils.degToRad(1),
        duration: 0.35,
        ease: 'power2.out',
      }).to(productGroup.rotation, {
        x: baseRotX,
        duration: 0.55,
        ease: 'power4.out',
      });
      tweens.push(tl);
    },
  };

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    for (const tw of tweens) {
      try { tw.kill(); } catch (e) {}
    }
    for (const handle of primitiveHandles) {
      try { handle?.cleanup?.(); } catch (e) {}
    }
    for (const dispose of disposables) {
      try { dispose(); } catch (e) {}
    }
    for (const t of textObjects) {
      try {
        t.parent?.remove(t);
        t.geometry?.dispose?.();
        t.material?.dispose?.();
      } catch (e) {}
    }
    rimLight.dispose?.();
  };

  return root;
}
